from pathlib import Path
import hashlib,base64,gzip,json
p=Path('tach-xep-pdf-v2.3.2/TachXepTrangPDF.cs')
raw=p.read_bytes()
expected='7fffc4bd0e880ccc246eb0b789970c82fcf83e80e6c240bcc845758377bdf317'
if hashlib.sha256(raw).hexdigest()!=expected: raise SystemExit('unexpected v2.4.2 reconstructed source')
lines=raw.decode('utf-8-sig').splitlines(True)
ops=json.loads(gzip.decompress(base64.b64decode('')).decode('utf-8'))
for i1,i2,text in reversed(ops): lines[i1:i2]=text.splitlines(True)
new=''.join(lines).encode('utf-8-sig')
if hashlib.sha256(new).hexdigest()!='76e2ba21bb36a5aee5e6eaf1a8f8d439e71bbda295bfca5c580f8b76522d69a3': raise SystemExit('patched v2.4.3 source checksum mismatch')
p.write_bytes(new)
launcher=Path('tach-xep-pdf-v2.3.2/launcher.cpp')
ls=launcher.read_text(encoding='utf-8-sig'); ls2=ls.replace('2.4.2','2.4.3')
if ls2==ls: raise SystemExit('launcher version marker missing')
launcher.write_text(ls2,encoding='utf-8-sig')
print('PATCH_V243_RESTORE_BASELINE_INTERACTIONS_OK')
